contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint[] memory vals, uint amount) public payable {
        require(tos.length > 0, "empty tos");
        require(tos.length == vals.length, "length mismatch");
        require(address(this).balance >= amount, "insufficient balance");

        address expectedFrom = c.from();
        address expectedCaddress = c.caddress();
        require(expectedFrom != address(0), "from zero");
        require(expectedCaddress != address(0), "caddress zero");

        bool reverted;
        bool returned;
        try c.transfer{value: amount}(tos, vals) returns (bool ok) {
            returned = ok;
            reverted = false;
        } catch {
            reverted = true;
            returned = false;
        }

        if (!reverted) {
            assert(returned == true);
            assert(c.from() == expectedFrom);
            assert(c.caddress() == expectedCaddress);
            assert(address(c).balance <= address(this).balance + amount);
        } else {
            assert(reverted == true);
        }
    }

    receive() external payable {}
}

