contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] memory _tos, uint[] memory v) public payable {
        bool reverted;
        // c.transfer can only be entered by the hard-coded sender; this test contract was the deployer
        // of c, so its own address is msg.sender for the call below.
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            assert(r == true);
        } catch {
            reverted = true;
        }
        // The only guaranteed failure mode observable here: empty receivers or not enough values
        // must revert; non-empty with enough values must not revert.
        assert(reverted == (_tos.length == 0 || v.length < _tos.length));
    }

    receive() external payable {}
}

